}
function startable(id, plotId) { return !!costOn(id, plotId) && wanted(id) && !onceBlocked(id) && inStock(id, plotId); }
function runningElsewhere(fam, plotId) {
  return plots.some((q) => q.id !== plotId && D.jobs[q.step.id] && (D.jobs[q.step.id].members ?? [D.jobs[q.step.id].family]).includes(fam));
}

// ---- combined farms (two farms side by side on one plot, e.g. Rares + Startlevine) ----

function comboOn(plotId) { return D.combos ? D.combos[str(plotId)] : undefined; }

/** Paid inputs of these combined-farm members not standing on the plot right now. */
function comboMissing(p, members) {
  const c = comboOn(p.id);
  const out = {};
  for (const m of members) for (const x of c.cells[m]) {
    const q = p.at(x.row, x.col);
    if (q && q.kind === x.kind && q.row === x.row && q.col === x.col) continue;
    out[x.kind] = (out[x.kind] ?? 0) + 1;
  }
  return out;
}
function affordable(missing) { return keys(missing).every((k) => inv(k) >= missing[k]); }

/** The combined farm instead of one member, when the other member would start here too and the stock pays both. */
function withCombo(p, id) {
  const c = comboOn(p.id);
  if (!c || !c.members.includes(id)) return id;
  const other = c.members.find((m) => m !== id);
  if (chooseNow(p.id, other) !== other) return id;
  return affordable(comboMissing(p, c.members)) ? c.id : id;
}

/** Running the combined farm: leave, or narrow to the member still worth running (its cells stay). Returns true when decided. */
function tendCombo(p, id, job) {
  const live = job.members.filter((m) => !satisfied(m));
  if (live.length === 0) { next(p, "satisfied " + id); return true; }
  if (!p.layoutShort()) {
    if (live.length < job.members.length) { enter(p, live[0], "narrow " + id); return true; }
    return false;
  }
  for (const m of live) if (affordable(comboMissing(p, [m]))) { enter(p, m, "narrow " + id); return true; }
  if (maturing(p, job)) { noteGuide(p, "stay", null, "finishing nearly grown targets, cannot refill"); return true; }
  next(p, "short " + id);
  return true;
}

/** Something a farm makes, rounded down to KNOBS.deferGrain steps: per-visit yields are measured averages. */
function madeNow(p) {
  const g = KNOBS.deferGrain > 0 ? KNOBS.deferGrain : 1;
  return Math.floor(net(p) / g) * g;
}

function familyOn(plotId) {
  const q = plots.find((x) => x.id === plotId);
  const j = q ? D.jobs[q.step.id] : undefined;
  return j ? j.family : "";
}

/** Would this job start on at least one plot (its layout differs per plot, so the cost does too)? */
function startableAnywhere(id) {
  return [1, 2, 3].some((q) => costOn(id, q) && startable(id, q));
}

const jobVariant = (fam) => (D.variants[fam] ?? [])[0];

/**
 * Why this visit would be deferred ("product: need X, one visit makes Y, consumer Z"), or "".
 *
 * The plot decides at the end of its session, but the consumer farm may only enter several cycles
 * later: the plan's need is then measured against stock that run is about to spend. When this visit
 * would mostly replace that stock (deferMinRatio) and the consumer can already start on another
 * plot, running something else first is free - the plan still needs the product, so this farm is
 * offered again next session, and the caller never idles to wait for the consumer.
 */
function deferReason(id, plotId) {
  const produces = D.jobs[id].produces;
  // Stock the consumer's next run eats is paid for by the items already standing in the inventory.
  if (!produces.some((p) => madeNow(p) > 0)) return "";
  for (const p of produces) {
    const need = net(p);
    if (!(need > 0)) continue;
    const per = D.plan[D.jobs[id].family]?.yield[p] ?? 0;
    // A visit that mostly overshoots the remaining need is the waste; a visit the consumer will
    // spend in full is normal pipeline fill.
    if (per < KNOBS.deferMinRatio * need) continue;
    // A consumer that can start before this plot's next session, on another plot.
    for (const c of D.topo) {
      if (c === D.jobs[id].family || D.jobs[c].family === familyOn(plotId)) continue;
      if (D.plan[c].use[p] === undefined || !startableAnywhere(c)) continue;
      return p + ":need=" + need.toFixed(1) + ",visit=" + per.toFixed(1) + ",consumer=" + c;
    }
  }
  return "";
}

/**
 * choose, but the first family choose would return is skipped when its focus variant (or itself)
 * is only replacing stock its own consumer is about to spend. The caller falls back to choose
 * when this returns null, so the plot never idles to wait (Knobs.deferStartable).
 */
function chooseDeferred(plotId, upTo) {
  for (const fam of D.order[str(plotId)]) {
    if (fam === upTo) return null;
    const id = chooseNow(plotId, fam);
    if (id === null) continue;
    if (deferReason(jobVariant(fam) ?? id, plotId) || deferReason(id, plotId)) continue;
    return fam;
  }
  return null;
}

/** The plan needs more of this family's products than the copies already running make. */
function moreThanRunning(fam, plotId) {
  const copies = plots.filter((q) => q.id !== plotId && D.jobs[q.step.id] && D.jobs[q.step.id].family === fam).length;
  const pl = D.plan[fam];
  if (!pl) return true;
  return keys(pl.yield).some((p) => net(p) > copies * pl.yield[p]);
}

/**
 * The first job this family would start here (focus variant or the full farm), or null.
 * isStartable(id, plotId) lets the deferred pass ask "would this start with the stock as it is
 * now" from inside the demand walk, which startable itself cannot (it would recurse).
 */
function chooseNow(plotId, fam, isStartable = startable) {
  if (KNOBS.single.includes(fam) && runningElsewhere(fam, plotId)) return null;
  if (KNOBS.dupOnlyIfNeeded && runningElsewhere(fam, plotId) && !moreThanRunning(fam, plotId)) return null;
  const vs = D.variants[fam] ?? [];
  // Focus variant first when only its products are short.
  for (const v of vs) {
    if (!isStartable(v, plotId)) continue;
    const others = D.jobs[fam].produces.filter((p) => !D.jobs[v].produces.includes(p));
    if (others.every((p) => inv(p) >= low(p) || !needed(p))) return v;
  }
  if (isStartable(fam, plotId)) return fam;
  for (const v of vs) if (D.jobs[v].fallback && isStartable(v, plotId)) return v;
  return null;
}

/** The first farm (in this plot's priority order) worth starting now, or null. */
function choose(plotId, upTo) {
  let order = D.order[str(plotId)];
  if (KNOBS.order === "rank" && upTo === null) order = order.map((f, i) => [f, i]).sort((a, b) => rankOf(b[0]) - rankOf(a[0]) || a[1] - b[1]).map((x) => x[0]);
  for (const fam of order) {
    if (fam === upTo) return null;
    const id = chooseNow(plotId, fam);
    if (id !== null) return id;
  }
  return null;
}

/** Bought supplies (Fermento / Dead Plants) are the only thing stopping a wanted farm. */
function blockedOnSupplies(plotId) {
  for (const fam of D.order[str(plotId)]) {
    for (const id of [...(D.variants[fam] ?? []), fam]) {
      const c = costOn(id, plotId);
      if (!c || !wanted(id)) continue;
      const short = keys(c).filter((k) => inv(k) < c[k]);
      if (short.length && short.every((k) => k === "fermento" || k === "dead_plant")) return true;
    }
  }
  return false;
}

/** Every paid input of the Cheesebite corner stands where the corner layout puts it. */
function cornerIntact(p) {
  const c = D.keepCorner[str(p.id)];
  return !!c && c.every((x) => { const q = p.at(x.row, x.col); return q && q.kind === x.kind && q.row === x.row && q.col === x.col && q.placed; });
}

/** Paid layout inputs this plot is missing right now (read-only), for the Guide's "what to place". */
function guideShort(p) {
  const out = [];
  for (const q of p.layout.plants) {
    if (q.origin !== "placed") continue;
    const at = p.at(q.row, q.col);
    if (at && at.kind === q.kind && at.row === q.row && at.col === q.col) continue;
    let found = null;
    for (const e of out) if (e.item === q.kind) found = e;
    if (found) found.count += 1; else out.push({ item: q.kind, count: 1 });
  }
  return out;
}

/** Record this plot's decision for the Guide. Pure bookkeeping: it changes no game state. */
function noteGuide(p, action, to, why, waitFor) {
  guideSerial += 1;
  guide[str(p.id)] = { serial: guideSerial, cycle, step: p.step.id, action, to, why,
    waitFor: waitFor ?? [], short: guideShort(p) };
}

function enter(p, id, why) {
  leftBecause[why] = (leftBecause[why] ?? 0) + 1;
  if (p.step.id === id) { noteGuide(p, "stay", null, why, guideWait[p.id]); return; }
  // Shellfruit from a Blast-Cheese farm whose Cheesebite corner still stands: keep the corner
  // (and its growing Cheesebites) for the Cheesebite focus, at no extra cost.
  if (id === "shellfruit" && D.keepCorner[str(p.id)] && cornerIntact(p)) id = "shellfruit-cheese";
  noteGuide(p, "enter", id, why, guideWait[p.id]);
  p.goto(id);
  entered[str(p.id)] = id;
  if (D.jobs[id]) builtOnce[D.jobs[id].family] = (builtOnce[D.jobs[id].family] ?? 0) + 1;
  // A growing Blastberry left over from the old farm would explode into the new one once grown:
  // break it while it is still unprimed (no blast) if it touches anything the new layout places.
  const placedCells = p.layout.plants.filter((q) => q.origin === "placed");
  for (const b of p.spawns("blastberry")) {
    if (b.primed || b.fullyGrown) continue;
    if (placedCells.some((q) => q.row <= b.row + 1 && q.row + q.size - 1 >= b.row - 1 && q.col <= b.col + 1 && q.col + q.size - 1 >= b.col - 1)) b.break();
  }
  // Entry chores the session already ran for the old step.
  p.runPhase("clearTargets");
  p.runPhase("fixGround");
}

/** Leave the current farm: next farm, or the hub / supply notice. */
function next(p, why) {
  let id = choose(p.id, null);
  // A first choice that would only replace stock its own consumer is about to spend waits a
  // session: take the next farm this plot could start instead, and never idle to wait for it.
  if (id !== null && KNOBS.deferStartable) {
    // The chosen job itself, or its family's focus variant (the top-up farm the hub would prefer).
    const reason = deferReason(id, p.id) || deferReason(jobVariant(D.jobs[id].family) ?? id, p.id);
    if (reason) {
      const later = chooseDeferred(p.id, null);
      const nextId = later === null ? null : chooseNow(p.id, later);
      if (nextId !== null) {
        if (KNOBS.deferLog) log("DEFER", cycle, p.id, id, "->", nextId, "why " + why, "reason " + reason);
        id = nextId;
      } else if (KNOBS.deferLog) log("DEFER-HOLD", cycle, p.id, id, "why " + why, "reason " + reason);
    }
  }
  if (id !== null) id = withCombo(p, id);
  if (id === null && KNOBS.idleNeed) {
    relaxed = true;
    id = choose(p.id, null);
    relaxed = false;
  }
  if (id !== null) return enter(p, id, why);
  if (blockedOnSupplies(p.id)) return enter(p, "supplies", why);
  if (KNOBS.idle === "stay" && D.jobs[p.step.id] && !p.layoutShort()) { noteGuide(p, "stay", null, "keeping " + p.step.id + " standing", guideWait[p.id]); return; } // keep it standing, no re-placing
  enter(p, "hub", why);
}

/** A target of a still-needed product is growing and at least KNOBS.drain grown: worth finishing. */
function maturing(p, job) {
  if (KNOBS.drain >= 1) return false;
  return p.targets.some((t) => t.filled && t.plant && !t.plant.fullyGrown && job.produces.includes(t.mutation) && needed(t.mutation)
    && t.plant.stage >= KNOBS.drain * Math.max(1, t.plant.growthStages));
}

// ---- special farms ----

// Guaranteed fragment yield of an Aloe harvest at this stage (the fractional extra is a bonus).
const ALOE_FRAGMENTS = [0,0,0,0,1,2,3,4,6,9,13,20,28,41,60,86,125,182,263,382,554,803,1164,1688,2448,3549,5146,7462];
/**
 * Guaranteed part of the greenhouse yield sum that scales a mutation's OWN item count. Current
 * game: none (the update "Fixed Plant Yield bonuses incorrectly applying to mutation items"), so 1.
 * With the simulator's legacyMutationYield setting the old sum applies (upgrade, Flora, effects).
 */
function yieldSum(plant) {
  if (!config.legacyMutationYield) return 1;
  let sum = 1 + stats.plantYieldUpgrade + 0.025 * Math.min(10, (stats.floraShard ?? 0));
  const fx = plant.effects;
  if (fx.includes("improved_harvest_boost")) sum += 0.3;
  else if (fx.includes("harvest_boost")) sum += 0.2;
  if (fx.includes("harvest_loss")) sum -= 0.2;
  return sum;
}
function aloeFloor(plant) {
  return Math.floor(ALOE_FRAGMENTS[Math.min(27, plant.stage)] * yieldSum(plant) + 0.000000001);
}

function pickTargets(p) {
  const step = p.step.id;
  if (step === "jelly") {
    const beans = p.spawns("magic_jellybean");
    // Items a Jellybean gives now: 1 at stage 12, +1 every 12 stages, scaled by yield.
    const items = (j) => j.stage < 12 ? 0 : Math.floor((1 + Math.floor((j.stage - 12) / 12)) * yieldSum(j) + 0.000000001);
    const stillNeeded = net("magic_jellybean");
    const finishNow = KNOBS.jellyFinish && stillNeeded > 0 && beans.sum((j) => items(j)) >= stillNeeded;
    for (const j of beans) {
      if ((j.stage >= KNOBS.jellyStage || (finishNow && j.stage >= 12)) && j.break()) picks.jellybeans += 1;
    }
  } else if (step === "aloe") {
    const missing = Math.max(0, (D.goal.all_in_aloe - inv("all_in_aloe")) * 9 - inv("all_in_aloe_fragment"));
    for (const a of p.spawns("all_in_aloe")) {
      if (missing > 0 && (a.stage >= KNOBS.aloeStage || aloeFloor(a) >= missing) && a.break()) picks.aloe += 1;
    }
  }
}

/** Shellfruit: once the placed Blastberries are primed, break only them; every Turtlellini is hit twice. */
function popShellfruit(p) {
  const berries = p.all("blastberry");
  if (berries.length && !berries.every((b) => b.primed)) return false;
  p.breakAll("blastberry");
  p.harvestAll("shellfruit");
  picks.shellfruit += 1;
  return true;
}

// ---- the session ----

function finish() {
  noteGuide(plot, "done", null, "goal complete");
  if (plot.step.id !== "done") plot.goto("done");
  plot.hold(false);
  plot.runPhase("stepChange"); // the Done step's own exit marks the flow finished
}

function tend(p) {
  const id = p.step.id;
  guideWait[p.id] = [];
  if (id === "done") { noteGuide(p, "done", null, "goal complete"); return; }
  pickTargets(p);
  if (id === "hub" || id === "supplies") return next(p, "idle");
  if (id === "shellfruit" || id === "shellfruit-cheese") {
    if (popShellfruit(p)) { next(p, "shellfruit popped"); return; }
    noteGuide(p, "stay", null, "waiting for the Blastberries to prime");
    return;
  }
  const job = D.jobs[id];
  if (job) {
    const held = job.produces.filter((p) => needed(p) && !(inv(p) >= high(p) && !KNOBS.stopOnNeed));
    for (const p of held) binding[id + ":" + p] = (binding[id + ":" + p] ?? 0) + (held.length === 1 ? 1 : 0.0001);
    // What the Guide needs to show "until you have N <item> (now M)": the same hold list plus marks.
    const wait = [];
    for (const k of held) wait.push({ item: k, have: inv(k), target: high(k) });
    guideWait[p.id] = wait;
  }
  if (job && job.members && tendCombo(p, id, job)) return;
  if (job && !job.members && job.special !== "noReplaceWhileGrowing") {
    // Leave: products satisfied, layout can't be refilled, or (Uncommons) an earlier farm is ready.
    if (satisfied(id)) {
      if (KNOBS.drainSatisfied && maturing(p, job)) { noteGuide(p, "stay", null, "finishing nearly grown targets"); return; } // nearly grown and still needed: finish them first
      return next(p, "satisfied " + id);
    }
    if (p.layoutShort()) {
      // A full farm that can't be refilled keeps going as a focus variant of its own family
      // (same cells: its inputs and growing targets stay) while that variant is still wanted.
      if (KNOBS.continueFamily && !job.focusOf) for (const v of D.variants[id] ?? []) if (startable(v, p.id)) return enter(p, v, "narrow " + id);
      if (maturing(p, job)) { noteGuide(p, "stay", null, "finishing nearly grown targets, cannot refill"); return; } // let the nearly grown targets finish (no re-placing: it is short)
      return next(p, "short " + id);
    }
    // The other half of a combined farm can start too: build it beside this one (in place, the
    // standing cells are kept and only its own inputs are spent).
    const c = comboOn(p.id);
    if (c && c.members.includes(id)) {
      const other = c.members.find((m) => m !== id);
      if (chooseNow(p.id, other) === other && affordable(comboMissing(p, c.members))) return enter(p, c.id, "join " + id);
    }
    // Farms with no paid inputs here (Lonelily field, Choconut focus) cost nothing to leave:
    // they yield the plot as soon as an earlier farm is ready.
    const free = keys(costOn(id, p.id) ?? {}).length === 0;
    if (free) {
      const earlier = choose(p.id, job.family);
      if (earlier !== null) return enter(p, earlier, "preempt " + id);
    }
    const hands = KNOBS.handover === "all" || (KNOBS.handover === "uncommons" && D.jobs[job.family].yieldWhenLow);
    if (hands && atLow(id) && !maturing(p, job)) {
      const earlier = choose(p.id, job.family);
      if (earlier !== null) return enter(p, earlier, "handover " + id);
    }
  }
  if (job && job.special === "noReplaceWhileGrowing" && p.count("devourer") === 0) {
    // No Devourer alive: a ring input destroyed by something other than decay (a blast, a teleport)
    // is never refreshed by the step's own exits. Rebuild the ring now, or move on if it can't be.
    const missing = p.layout.plants.some((q) => { const at = p.at(q.row, q.col); return q.origin === "placed" && !(at && at.kind === q.kind && at.row === q.row && at.col === q.col); });
    if (missing) {
      if (p.layoutShort()) return next(p, "short " + id);
      leftBecause["rebuild " + id] = (leftBecause["rebuild " + id] ?? 0) + 1;
      noteGuide(p, "refresh", id, "rebuild " + id, guideWait[p.id]);
      p.restart();
      return;
    }
  }
  // Other exits (Devourer refresh, Aloe goal reached), read from the step.
  const due = p.exitDue();
  if (due === "done") { noteGuide(p, "done", null, "the step's own exit finished the flow"); return; }
  if (due === "hub") return next(p, "left " + id);
  if (due === id) {
    // Refresh (Devourer after a harvest/decay): re-enter; its on-arrival checks send it
    // to the hub when the stock can't rebuild it.
    leftBecause["refresh " + id] = (leftBecause["refresh " + id] ?? 0) + 1;
    noteGuide(p, "refresh", id, "refresh " + id, guideWait[p.id]);
    p.restart();
    if (p.step.id === "hub") next(p, "refresh short");
    return;
  }
  if (due !== null) return enter(p, due, "special " + id);
  // Stay: re-place what is missing only when the stock covers every gap.
  if (!p.layoutShort()) { noteGuide(p, "stay", null, "working " + id, guideWait[p.id]); p.runPhase("maintain"); }
  else noteGuide(p, "stay", null, "working " + id, guideWait[p.id]);
}

function afterSession() {
  if (complete()) return finish();
  tend(plot);
  if (complete()) finish();
}

function onCycleEnd() {
  // A later plot's harvest may finish the goal after this plot's session.
  if (online && complete() && plot.step.id !== "done") finish();
}

function onStart() {
  if (complete()) return finish();
  tend(plot);
}
